public function getProductCategoryTrail($product_id) {
	$deepest = $this->db->query("SELECT p2c.category_id FROM " . DB_PREFIX . "product_to_category p2c LEFT JOIN " . DB_PREFIX . "category c ON (c.category_id = p2c.category_id) LEFT JOIN " . DB_PREFIX . "category_to_store c2s ON (c2s.category_id = p2c.category_id) LEFT JOIN " . DB_PREFIX . "category_path cp ON (cp.category_id = p2c.category_id) WHERE p2c.product_id = '" . (int)$product_id . "' AND c.status = '1' AND c2s.store_id = '" . (int)$this->config->get('config_store_id') . "' GROUP BY p2c.category_id ORDER BY MAX(cp.level) DESC, p2c.category_id ASC LIMIT 1");

	if (!$deepest->num_rows) {
		return array();
	}

	$query = $this->db->query("SELECT cp.path_id AS category_id, cd.name, c.status FROM " . DB_PREFIX . "category_path cp LEFT JOIN " . DB_PREFIX . "category c ON (c.category_id = cp.path_id) LEFT JOIN " . DB_PREFIX . "category_description cd ON (cd.category_id = cp.path_id AND cd.language_id = '" . (int)$this->config->get('config_language_id') . "') WHERE cp.category_id = '" . (int)$deepest->row['category_id'] . "' ORDER BY cp.level ASC");

	foreach ($query->rows as $row) {
		// A disabled parent would produce a dead link, so skip the trail entirely.
		if (!$row['status'] || $row['name'] === null) {
			return array();
		}
	}

	return $query->rows;
}

if (!isset($this->request->get['path']) && isset($this->request->get['product_id']) && $data['breadcrumbs']) {
	$category_trail = $this->model_catalog_category->getProductCategoryTrail((int)$this->request->get['product_id']);

	if ($category_trail) {
		// Keep "Home" first, then the category trail, then any core breadcrumbs (manufacturer, search).
		$category_breadcrumbs = array(array_shift($data['breadcrumbs']));
		$category_path = '';

		foreach ($category_trail as $category) {
			$category_path .= ($category_path ? '_' : '') . (int)$category['category_id'];

			$category_breadcrumbs[] = array(
				'text' => $category['name'],
				'href' => $this->url->link('product/category', 'path=' . $category_path)
			);
		}

		$data['breadcrumbs'] = array_merge($category_breadcrumbs, $data['breadcrumbs']);
	}
}
